            labelSpan.className = 'benchmarked-failed-inspections-label';
            labelSpan.appendChild(document.createTextNode('Pre-existing '));

            var badge = document.createElement('span');
            badge.className = 'benchmark-badge';
            badge.textContent = 'Non-blocking';
            labelSpan.appendChild(badge);

            labelSpan.appendChild(document.createTextNode(' ('));
            var countSpan = document.createElement('span');
            countSpan.className = 'benchmarked-count';
            countSpan.textContent = '0';
            labelSpan.appendChild(countSpan);
            labelSpan.appendChild(document.createTextNode(')'));
